local function getClientLayoutWindow(layoutId)
    local layout = RootGuiLayout.Instance():getLayout(layoutId)
    if not layout then
        return nil
    end
    return layout:getRootWindow()
end

local function hideEngineWindow(name)
    local window = GUIManager:getWindowByName(name)
    if not window then
        return
    end
    local xPos = window:GetXPosition()
    if xPos[1] < -1 then
        return
    end
    window:SetXPosition({ xPos[1] - 2, xPos[2] })
    if not isTest and Platform.isWindow() then
        return
    end
    window:SetVisible(false)
end

local function showEngineWindow(name)
    local window = GUIManager:getWindowByName(name)
    if not window then
        return
    end
    local xPos = window:GetXPosition()
    if xPos[1] >= 0 then
        return
    end
    window:SetXPosition({ xPos[1] + 2, xPos[2] })
    if not isTest and Platform.isWindow() then
        return
    end
    window:SetVisible(true)
end

