    end
    return layout
end

function GUIManager:onTick(frameTime, renderDt)
    self:runQueue()
    for name, layout in pairs(Layouts) do
        if layout:isShow() then
            layout:onTick(frameTime, renderDt)
        end
    end
    for name, layout in pairs(SubLayouts) do
        if layout:isShow() then
            layout:onTick(frameTime, renderDt)
        end
    end
    if LockQueueTick then
        return
    end
    if #ShowQueue <= 0 then
        return
    end
    local item = ShowQueue[1]
    if item.tag == false then
        if not GuideWindow:IsVisible() then
            if CEvents.ShowQueueLayoutEvent:invoke(item.layout) then
                item.layout:show(unpack(item.params or {}))
            end
            item.tag = true
        end
    else
        if not item.layout:isShow() then
            table.remove(ShowQueue, 1)
        end
    end
end

function GUIManager:showMainControlLayout()
    for name, layout in pairs(Layouts) do
        if layout:isMainControl() then
            layout:show()
        end
    end
    for name, layout in pairs(SubLayouts) do
        if layout:isMainControl() then
            layout:show()
        end
    end
end

function GUIManager:hideAllLayout(force)
    for name, layout in pairs(Layouts) do
