---@param layout IGUILayout
---@param index number|nil
function GUIManager:addShowQueue(layout, index, params)
    if layout == nil then
        return
    end
    if layout:isShow() then
        return
    end
    for _, item in pairs(ShowQueue) do
        if item.layout == layout then
            return
        end
    end
    index = index or #ShowQueue + 1
    table.insert(ShowQueue, index, { layout = layout, tag = false, params = params })
end

function GUIManager:removeShowQueue(layout)
    for pos, item in pairs(ShowQueue) do
        if item.layout == layout then
            table.remove(ShowQueue, pos)
            break
        end
    end
end

