local FuncQueue = {}

function GUIManager:runQueue()
    local exeTime = 0
    local curTime = os.clock()
    while (#FuncQueue > 0 and exeTime < 0.02) do
        FuncQueue[1]()
        table.remove(FuncQueue, 1)
        exeTime = os.clock() - curTime
    end
end

function GUIManager:registerQueue(func)
    if isTickLoad then
        table.insert(FuncQueue, func)
    else
        func()
    end
end

