function GUIManager:setWindowsAlphaToZero(names, setZero)
    if setZero then
        self.alphaRecord = self.alphaRecord or {}
        ---@param window GUIWindow
        local function recordAlpha(window)
            local name = window:GetName()
            self.alphaRecord[name] = window:GetAlpha()
            local count = window:GetChildCount()
            if count == 0 then
                return
            end
            for i = 1, count do
                recordAlpha(window:GetChildByIndex(i - 1))
            end
        end
        for _, name in pairs(names) do
            local window = GUIManager:getWindowByName(name)
            if window then
                recordAlpha(window)
                window:SetAlpha(0)
            end
        end
    else
        ---@param window GUIWindow
        local function restoreAlpha(window)
            local name = window:GetName()
            window:SetAlpha(self.alphaRecord[name] or 1)
            local count = window:GetChildCount()
            if count == 0 then
                return
            end
            for i = 1, count do
                restoreAlpha(window:GetChildByIndex(i - 1))
            end
        end
        for _, name in pairs(names) do
            local window = GUIManager:getWindowByName(name)
            if window then
                restoreAlpha(window)
            end
        end
        self.alphaRecord = {}
    end
end

---@param root GUIWindow
local function hideAllChildren(root, level, excludedMap, hideResult)
    local count = root:GetChildCount()
    local rootName = root:GetName()
    if excludedMap[rootName] then
        return
    end
    local allChildHide = true
    for index = 0, count - 1 do
        local wnd = root:GetChildByIndex(index)
        local name = wnd:GetName()
        if excludedMap[name] then
            allChildHide = false
            goto CONTINUE
        end
        if level > 0 and wnd:GetChildCount() > 0 then
            hideAllChildren(wnd, level - 1, excludedMap, hideResult)
        else
            if wnd:IsVisible() then
                hideEngineWindow(name)
                hideResult[name] = true
            end
        end
        :: CONTINUE ::
    end
    if allChildHide and root:IsVisible() then
        hideEngineWindow(rootName)
        hideResult[rootName] = true
    end
end

function GUIManager:hideAllWindow(excludedMap)
    local root = GUISystem.Instance():GetRootWindow()
    if not root then
        return
    end
    local level = 2
    local hideResult = {}
    hideAllChildren(root, level, excludedMap, hideResult)
    return function()
        for name, _ in pairs(hideResult) do
            showEngineWindow(name)
        end
    end
end

function GUIManager:hideAllWindowsExcept(whiteList)
    self:restoreAllWindows()
    local excepts = {}
    for _, wnd in pairs(whiteList or {}) do
        if type(wnd) == "string" then
            excepts[wnd] = true
        else
            excepts[wnd:GetName()] = true
        end
    end
    self.restoreHideWindowsFunc = self:hideAllWindow(excepts)
end

function GUIManager:restoreAllWindows()
    if not self.restoreHideWindowsFunc then
        return
    end
    self.restoreHideWindowsFunc()
    self.restoreHideWindowsFunc = nil
end

function GUIManager:getAllWindowNames()
    local ret = {}
    local function findAllName(_root, _level)
        local count = _root:GetChildCount()
        table.insert(ret, _root:GetName())
        for index = 0, count - 1 do
            local wnd = _root:GetChildByIndex(index)
            if wnd:IsVisible() then
                table.insert(ret, wnd:GetName())
            end
            if _level > 0 and wnd:GetChildCount() > 0 then
                findAllName(wnd, _level - 1)
            end
        end
    end
    local level = 2
    local root = GUISystem.Instance():GetRootWindow()
    findAllName(root, level)
    return ret
end

